drop policy if exists mithaq_chat_reactions_read_participant on public.mithaq_chat_message_reactions;
create policy mithaq_chat_reactions_read_participant on public.mithaq_chat_message_reactions for select to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active') and exists(select 1 from public.messages m where m.id=message_id and (m.sender_id=(select auth.uid()) or m.recipient_id=(select auth.uid()))));
drop policy if exists mithaq_chat_reactions_insert_own on public.mithaq_chat_message_reactions;
create policy mithaq_chat_reactions_insert_own on public.mithaq_chat_message_reactions for insert to authenticated with check (user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active') and exists(select 1 from public.messages m where m.id=message_id and m.deleted_for_everyone_at is null and (m.sender_id=(select auth.uid()) or m.recipient_id=(select auth.uid()))));
drop policy if exists mithaq_chat_reactions_delete_own on public.mithaq_chat_message_reactions;
create policy mithaq_chat_reactions_delete_own on public.mithaq_chat_message_reactions for delete to authenticated using (user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active'));
drop policy if exists mithaq_chat_pins_read_participant on public.mithaq_chat_message_pins;
create policy mithaq_chat_pins_read_participant on public.mithaq_chat_message_pins for select to authenticated using (user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active') and exists(select 1 from public.messages m where m.id=message_id and (m.sender_id=(select auth.uid()) or m.recipient_id=(select auth.uid()))));
