create policy mithaq_chat_pins_insert_own on public.mithaq_chat_message_pins for insert to authenticated with check (user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active') and exists(select 1 from public.messages m where m.id=message_id and (m.sender_id=(select auth.uid()) or m.recipient_id=(select auth.uid()))));
drop policy if exists mithaq_chat_pins_delete_own on public.mithaq_chat_message_pins;
create policy mithaq_chat_pins_delete_own on public.mithaq_chat_message_pins for delete to authenticated using (user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active'));
drop policy if exists mithaq_chat_privacy_own on public.mithaq_chat_privacy_settings;
create policy mithaq_chat_privacy_own on public.mithaq_chat_privacy_settings for all to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active')) with check(user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.account_status='active'));